package com.sunny.notificationlog.data

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * One captured notification.
 *
 * Learning notes on the field choices:
 *
 * - [id] is auto-generated by SQLite; we always insert with the default 0 and
 *   let Room/SQLite assign the real row id.
 *
 * - [packageName] is the technical source app id (e.g. org.telegram.messenger).
 *   [appLabel] is the human-readable name shown in launchers ("Telegram"),
 *   resolved via PackageManager at capture time and stored denormalized here so
 *   the future list UI never needs to touch PackageManager again. It also stays
 *   correct-ish even if an app is later uninstalled.
 *
 * - title/text are never null: the service substitutes placeholders like
 *   "(no title)" for missing extras before inserting, keeping this table's
 *   columns non-null and downstream code simple.
 *
 * - [timestamp] is `StatusBarNotification.postTime` — epoch milliseconds of
 *   when the notification was first posted. Storing raw millis (not a formatted
 *   string) keeps sorting trivial and formatting a presentation concern.
 */
@Entity(tableName = "notifications")
data class NotificationEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val packageName: String,
    val appLabel: String,
    val title: String,
    val text: String,
    val timestamp: Long
)
